CREATE TABLE IF NOT EXISTS public.payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL, student_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, amount numeric(12,2) NOT NULL, currency text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','success','failed')), provider text NOT NULL DEFAULT 'paystack', created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz);
GRANT SELECT ON public.payment_transactions TO authenticated; GRANT ALL ON public.payment_transactions TO service_role; ALTER TABLE public.payment_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "student own payments" ON public.payment_transactions FOR SELECT TO authenticated USING(student_id=auth.uid() OR public.is_admin());
CREATE POLICY "admin payment management" ON public.payment_transactions FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE OR REPLACE FUNCTION public.activate_course_after_payment(_reference text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p payment_transactions; BEGIN SELECT * INTO p FROM public.payment_transactions WHERE reference=_reference AND status='success' FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; INSERT INTO public.enrollments(student_id,course_id,status) VALUES(p.student_id,p.course_id,'active') ON CONFLICT (student_id,course_id) DO UPDATE SET status='active'; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.activate_course_after_payment(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.activate_course_after_payment(text) TO service_role;
